<script lang="ts">
  import { formatDate, formatNumber } from '../lib/format';
  import type { EventCardData } from '../lib/types';

  export let card: EventCardData;
  export let runId: string;

  $: statusLabel = card.status.replaceAll('_', ' ');
</script>

<article class:unavailable={card.probability_pct === null} class="event-card">
  <header>
    <span class="evidence-chip">Evidência {card.evidence_level}</span>
    <span class="status-chip">{statusLabel}</span>
  </header>
  <h3>{card.title}</h3>
  {#if card.probability_pct !== null}
    <div
      class="event-probability"
      data-value={card.probability_pct}
      data-kind="Probabilidade estimada"
      data-run-id={runId}
      data-evidence={card.evidence_ids.join(',')}
    >{formatNumber(card.probability_pct)}%</div>
    <p class="event-change">
      {#if card.variation_pp !== null}
        Variação: {card.variation_pp > 0 ? '+' : ''}{formatNumber(card.variation_pp)} p.p.
      {:else}
        Sem run anterior comparável
      {/if}
    </p>
  {:else}
    <div class="event-unavailable">Indisponível</div>
    <p class="event-change">
      Massa não modelada:
      <span
        data-value={(card.unmodeled_mass ?? 0) * 100}
        data-kind="Massa não modelada"
        data-run-id={runId}
        data-evidence={card.evidence_ids.join(',')}
      >{formatNumber((card.unmodeled_mass ?? 0) * 100)}%</span>
    </p>
  {/if}
  <dl>
    <div><dt>Data-alvo</dt><dd>{formatDate(card.target_date)}</dd></div>
    <div><dt>Por que mudou</dt><dd>{card.why_changed}</dd></div>
  </dl>
  <details>
    <summary>Regra de resolução</summary>
    <p>{card.rules}</p>
  </details>
</article>
