<script lang="ts">
  import AuditValue from '../components/AuditValue.svelte';
  import DataTable from '../components/DataTable.svelte';
  import { formatDate, formatNumber } from '../lib/format';
  import type { Overview, PollRow, PollsPayload } from '../lib/types';

  export let payload: PollsPayload;
  export let overview: Overview;
  export let initialHouse = '';

  let selectedHouse = initialHouse;
  let selectedMode = '';
  let selectedStatus = '';
  let search = '';
  $: candidateById = new Map(overview.candidates.map((candidate) => [candidate.id, candidate]));
  $: houses = Array.from(new Map(payload.polls.map((poll) => [poll.institute_id, poll.institute_name])).entries());
  $: modes = Array.from(new Set(payload.polls.map((poll) => poll.mode))).sort();
  $: filtered = payload.polls.filter((poll) => {
    if (selectedHouse && poll.institute_id !== selectedHouse) return false;
    if (selectedMode && poll.mode !== selectedMode) return false;
    if (selectedStatus === 'included' && !poll.included) return false;
    if (selectedStatus === 'excluded' && poll.included) return false;
    const needle = search.trim().toLocaleLowerCase('pt-BR');
    return !needle || `${poll.registration_no} ${poll.institute_name} ${poll.contractor}`.toLocaleLowerCase('pt-BR').includes(needle);
  });

  function exportSelection(format: 'json' | 'csv'): void {
    let body: string;
    let type: string;
    if (format === 'json') {
      body = JSON.stringify({ run_id: payload.run_id, fixture: payload.fixture, polls: filtered }, null, 2);
      type = 'application/json';
    } else {
      const header = ['run_id', 'registro', 'casa', 'campo_fim', 'n', 'modo', 'incluida', 'motivo', 'evidence_id'];
      const rows = filtered.map((poll) => [poll.run_id, poll.registration_no, poll.institute_name, poll.field_end, poll.sample_size, poll.mode, poll.included, poll.reason_code, poll.evidence_id]);
      body = [header, ...rows].map((row) => row.map((value) => `"${String(value).replaceAll('"', '""')}"`).join(',')).join('\n');
      type = 'text/csv;charset=utf-8';
    }
    const url = URL.createObjectURL(new Blob([body], { type }));
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `pesquisas-${payload.run_id}.${format}`;
    anchor.click();
    URL.revokeObjectURL(url);
  }

  function top(items: PollRow['published']) {
    return items.slice(0, 2);
  }
</script>

<section class="page-stack" aria-labelledby="polls-title">
  <header class="page-hero compact-hero">
    <p class="eyebrow">Dados e decisões</p>
    <h1 id="polls-title">Pesquisas</h1>
    <p>Todas as entradas permanecem visíveis. Inclusão ou exclusão vem de regra versionada e do log; evidência pendente nunca alimenta o agregado.</p>
  </header>

  <div class="poll-filters" aria-label="Filtros de pesquisas">
    <label><span>Casa</span><select bind:value={selectedHouse}><option value="">Todas</option>{#each houses as [id, name]}<option value={id}>{name}</option>{/each}</select></label>
    <label><span>Modo</span><select bind:value={selectedMode}><option value="">Todos</option>{#each modes as mode}<option value={mode}>{mode}</option>{/each}</select></label>
    <label><span>Situação</span><select bind:value={selectedStatus}><option value="">Todas</option><option value="included">Incluídas</option><option value="excluded">Fora do agregado</option></select></label>
    <label class="search-filter"><span>Registro ou texto</span><input bind:value={search} type="search" placeholder="BR-00000/2022" /></label>
    <div class="export-actions"><button type="button" onclick={() => exportSelection('csv')}>Baixar CSV</button><button type="button" onclick={() => exportSelection('json')}>Baixar JSON</button></div>
  </div>

  <p class="filter-result" aria-live="polite"><strong>{filtered.length}</strong> de {payload.polls.length} entradas · seleção ligada ao <code>{payload.run_id}</code></p>

  <DataTable label="Tabela completa de pesquisas">
    <table class="poll-table">
      <thead><tr><th>Campo/casa</th><th>Ficha</th><th>Publicado</th><th>Ajustada</th><th class="num">Peso</th><th>Decisão</th><th>Evidência</th></tr></thead>
      <tbody>
        {#each filtered as poll}
          <tr id={poll.registration_no}>
            <th scope="row"><strong>{formatDate(poll.field_end)}</strong><small>{poll.institute_name}</small><small>{poll.contractor}</small></th>
            <td>
              <code>{poll.registration_no}</code>
              <small><span data-value={poll.sample_size} data-kind="Publicado" data-run-id={poll.run_id} data-evidence={poll.evidence_id}>n={poll.sample_size.toLocaleString('pt-BR')}</span> · {poll.mode} · {poll.scenario.base}</small>
              <small>Publicação: {formatDate(poll.published_at)} · base da amostra: {poll.sample_size_basis ?? 'declarada'}</small>
              <details><summary>Ficha art. 10</summary><dl class="mini-definition"><div><dt>Período</dt><dd>{formatDate(poll.article_10.field_period.start)}–{formatDate(poll.article_10.field_period.end)}</dd></div><div><dt>Margem</dt><dd data-value={poll.article_10.margin_of_error} data-kind="Publicado" data-run-id={poll.run_id} data-evidence={poll.evidence_id}>±{formatNumber(poll.article_10.margin_of_error)} p.p.</dd></div><div><dt>Confiança</dt><dd data-value={poll.article_10.confidence_level} data-kind="Publicado" data-run-id={poll.run_id} data-evidence={poll.evidence_id}>{formatNumber(poll.article_10.confidence_level)}%</dd></div><div><dt>Amostra</dt><dd>{poll.article_10.sample_size.toLocaleString('pt-BR')}</dd></div><div><dt>Empresa/contratante</dt><dd>{poll.article_10.institute} / {poll.article_10.contractor}</dd></div><div><dt>Registro</dt><dd>{poll.article_10.registration_number}</dd></div></dl></details>
            </td>
            <td>{#each top(poll.published) as item}<span class="metric-pair">{candidateById.get(item.candidate_id)?.short_name} <AuditValue metric={item.value} compact /></span>{/each}</td>
            <td>{#if poll.adjusted.length}{#each top(poll.adjusted) as item}<span class="metric-pair">{candidateById.get(item.candidate_id)?.short_name} <AuditValue metric={item.value} compact /></span>{/each}{:else}<span class="not-applicable">Não calculada</span>{/if}</td>
            <td class="num">{#if poll.weight}<AuditValue metric={poll.weight} compact />{:else}<span aria-label="Sem peso">—</span>{/if}</td>
            <td><span class:included={poll.included} class="decision-chip">{poll.included ? 'Incluída' : 'Fora'}</span><small>{poll.reason_detail}</small></td>
            <td><a href={poll.evidence_url} aria-label={`Abrir evidência ${poll.evidence_id}`}>{poll.evidence_id} →</a></td>
          </tr>
        {/each}
      </tbody>
    </table>
  </DataTable>
</section>
