<script lang="ts">
  import { onMount } from 'svelte';
  import * as Plot from '@observablehq/plot';
  import { candidateColor } from '../lib/palette';
  import { formatDate, formatNumber } from '../lib/format';
  import type { Candidate, TrendPoint } from '../lib/types';

  export let points: TrendPoint[];
  export let candidates: Candidate[];
  export let title = 'Tendência das estimativas ajustadas';

  let container: HTMLDivElement;
  let resizeObserver: ResizeObserver | undefined;
  $: candidateById = new Map(candidates.map((candidate) => [candidate.id, candidate]));

  function draw(): void {
    if (!container || !points.length) return;
    container.replaceChildren();
    const domain = candidates.map((candidate) => candidate.id);
    const range = candidates.map((candidate) => candidateColor(candidate.id, candidates));
    const chart = Plot.plot({
      width: Math.max(320, container.clientWidth),
      height: container.clientWidth < 600 ? 260 : 340,
      marginLeft: 44,
      marginRight: 28,
      marginBottom: 42,
      style: { background: 'transparent', color: '#52514e', fontFamily: 'inherit', fontSize: '12px' },
      x: { type: 'utc', label: null, grid: false, ticks: 5 },
      y: { domain: [0, 60], label: '% em válidos', grid: true, ticks: 6 },
      color: { domain, range, legend: true },
      marks: [
        Plot.ruleY([0, 10, 20, 30, 40, 50, 60], { stroke: '#e1e0d9', strokeWidth: 1 }),
        Plot.lineY(points, {
          x: (point) => new Date(`${point.date}T12:00:00`),
          y: (point) => point.value.q50,
          stroke: 'candidate_id',
          z: 'candidate_id',
          strokeWidth: 2,
        }),
        Plot.dot(points, {
          x: (point) => new Date(`${point.date}T12:00:00`),
          y: (point) => point.value.q50,
          fill: 'candidate_id',
          stroke: '#fcfcfb',
          strokeWidth: 2,
          r: 5,
          tip: true,
          title: (point) => `${candidateById.get(point.candidate_id)?.name ?? point.candidate_id}\n${formatDate(point.date)}\nAjustada: ${formatNumber(point.value.q50)}%\n${point.registration_no}`,
        }),
      ],
    });
    chart.setAttribute('role', 'img');
    chart.setAttribute('aria-label', `${title}. Linhas por candidatura; cada ponto corresponde a uma pesquisa ajustada. A tabela abaixo contém os mesmos valores.`);
    chart.querySelectorAll('g[aria-label]').forEach((node) => node.removeAttribute('aria-label'));
    container.append(chart);
  }

  onMount(() => {
    draw();
    resizeObserver = new ResizeObserver(draw);
    resizeObserver.observe(container);
    return () => resizeObserver?.disconnect();
  });

  $: if (container && points && candidates) {
    queueMicrotask(draw);
  }
</script>

<div class="chart-frame">
  <div bind:this={container} class="plot-container"></div>
  <details class="chart-table">
    <summary>Tabela acessível da tendência</summary>
    <div class="table-shell" role="region" aria-label="Valores da tendência">
      <table>
        <thead><tr><th>Data</th><th>Casa</th><th>Candidatura</th><th class="num">Ajustada</th><th>Evidência</th></tr></thead>
        <tbody>
          {#each points as point}
            <tr>
              <td>{formatDate(point.date)}</td>
              <td>{point.institute_id}</td>
              <td>{candidateById.get(point.candidate_id)?.short_name ?? point.candidate_id}</td>
              <td class="num" data-value={point.value.q50} data-kind={point.value.kind} data-run-id={point.value.run_id} data-evidence={point.value.evidence_ids.join(',')}>{formatNumber(point.value.q50)}%</td>
              <td><code>{point.value.evidence_ids.join(', ')}</code></td>
            </tr>
          {/each}
        </tbody>
      </table>
    </div>
  </details>
</div>
