  import { formatDate } from '../lib/format';
  import type { HousesPayload, Overview } from '../lib/types';

  export let houses: HousesPayload;
  export let overview: Overview;

  $: candidateById = new Map(overview.candidates.map((candidate) => [candidate.id, candidate]));
  const top = <T,>(items: T[]) => items.slice(0, 2);
</script>

