            {#each top(house.adjusted) as item}<small>{candidateById.get(item.candidate_id)?.short_name} <AuditValue metric={item.value} compact /></small>{/each}
          </div>
          <div>
            <span class="kind-chip">Projeção</span>
            {#each top(house.projection) as item}<small>{candidateById.get(item.candidate_id)?.short_name} <AuditValue metric={item.value} compact /></small>{/each}
          </div>
        </div>
        <footer class="card-footer">
