<script lang="ts">
  import { onMount } from 'svelte';
  import Footer from './components/Footer.svelte';
  import { loadCoreData, loadHouse, loadOperations } from './lib/data';
  import { formatDateTime } from './lib/format';
  import type { CoreData, HouseDetail } from './lib/types';
  import Home from './pages/Home.svelte';
  import House from './pages/House.svelte';
  import Institutes from './pages/Institutes.svelte';
  import Lab from './pages/Lab.svelte';
  import Methods from './pages/Methods.svelte';
  import Polls from './pages/Polls.svelte';

  let data: CoreData | null = null;
  let detail: HouseDetail | null = null;
  let detailError = '';
  let requestedHouse = '';
  let error = '';
  let path = window.location.pathname;
  let search = window.location.search;
  let period = new URLSearchParams(search).get('period') ?? '30';

  $: houseId = path.startsWith('/institutos/') ? decodeURIComponent(path.split('/')[2] ?? '') : '';
  $: initialHouse = new URLSearchParams(search).get('casa') ?? '';
  $: if (data && houseId && requestedHouse !== houseId) {
    void fetchHouse(houseId);
  }
  $: document.title = pageTitle(path);

  async function fetchHouse(id: string): Promise<void> {
    if (!data) return;
    requestedHouse = id;
    detail = null;
    detailError = '';
    try {
      detail = await loadHouse(id, data.manifest.run_id);
    } catch (reason) {
      detailError = reason instanceof Error ? reason.message : 'Não foi possível abrir a ficha.';
    }
  }

  function pageTitle(currentPath: string): string {
    if (currentPath === '/') return 'Visão geral · Central de probabilidades';
    if (currentPath === '/institutos') return 'Institutos · Central de probabilidades';
    if (currentPath.startsWith('/institutos/')) return 'Ficha do instituto · Central de probabilidades';
    if (currentPath === '/pesquisas') return 'Pesquisas · Central de probabilidades';
    if (currentPath === '/metodologia') return 'Metodologia · Central de probabilidades';
    if (currentPath === '/laboratorio') return 'Laboratório · Central de probabilidades';
    return 'Central de probabilidades · replay local';
  }

  function syncLocation(): void {
    path = window.location.pathname;
    search = window.location.search;
    period = new URLSearchParams(search).get('period') ?? '30';
  }

  function navigate(url: URL): void {
    window.history.pushState({}, '', `${url.pathname}${url.search}${url.hash}`);
    syncLocation();
    if (url.hash) {
      requestAnimationFrame(() => document.querySelector(url.hash)?.scrollIntoView({ behavior: 'smooth' }));
    } else {
      window.scrollTo({ top: 0, behavior: 'auto' });
    }
  }

  function onPeriodChange(value: string): void {
    const url = new URL(window.location.href);
    url.searchParams.set('period', value);
    navigate(url);
  }

  onMount(() => {
    let operationsTimer: ReturnType<typeof setInterval> | undefined;
    const clickHandler = (event: MouseEvent) => {
      const target = event.target as Element | null;
      const anchor = target?.closest<HTMLAnchorElement>('a[data-route]');
      if (!anchor || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
      const url = new URL(anchor.href, window.location.href);
      if (url.origin !== window.location.origin) return;
      event.preventDefault();
      navigate(url);
    };
    const popHandler = () => syncLocation();
    document.addEventListener('click', clickHandler);
    window.addEventListener('popstate', popHandler);

    void loadCoreData()
      .then((loaded) => {
        data = loaded;
        operationsTimer = setInterval(() => {
          void loadOperations().then((operations) => {
            if (data) data = { ...data, operations };
          }).catch(() => undefined);
        }, 30_000);
      })
      .catch((reason) => {
        error = reason instanceof Error ? reason.message : 'Falha ao carregar os contratos do dashboard.';
      });

    return () => {
      document.removeEventListener('click', clickHandler);
      window.removeEventListener('popstate', popHandler);
      if (operationsTimer) clearInterval(operationsTimer);
    };
  });
</script>

<a class="skip-link" href="#main-content">Pular para o conteúdo</a>

<header class="topbar">
  <div class="topbar-inner">
    <a class="brand" href="/" data-route aria-label="Central de probabilidades — ir para a Visão geral">
      <span class="brand-mark" aria-hidden="true">CP</span>
      <span><strong>Central de probabilidades</strong><small>pesquisas com evidência</small></span>
    </a>
    <nav class="main-nav" aria-label="Navegação principal">
      <a class:active={path === '/'} href="/" data-route>Visão geral</a>
      <a class:active={path.startsWith('/institutos')} href="/institutos" data-route>Institutos</a>
      <a class:active={path === '/pesquisas'} href="/pesquisas" data-route>Pesquisas</a>
      <a class:active={path === '/laboratorio'} href="/laboratorio" data-route>Laboratório</a>
      <a class:active={path === '/metodologia'} href="/metodologia" data-route>Metodologia</a>
    </nav>
    <div class="topbar-actions">
      <label class="dispute-select"><span class="sr-only">Disputa</span><select aria-label="Disputa" disabled><option>Replay 2022 · 1º turno</option></select></label>
      {#if data}<span class="updated">As-of {formatDateTime(data.manifest.generated_at)}</span>{/if}
      <a class="download-button" href="/data/latest/polls.json" download>Baixar dados</a>
    </div>
  </div>
</header>

<main id="main-content" tabindex="-1">
  {#if error}
    <section class="load-state error-state" role="alert">
      <p class="eyebrow">Falha de contrato</p>
      <h1>O dashboard não pôde abrir os dados.</h1>
      <p>{error}</p>
      <p>Execute novamente o pipeline e valide os JSON Schemas antes do build.</p>
    </section>
  {:else if !data}
    <section class="load-state" aria-live="polite"><span class="loading-mark" aria-hidden="true"></span><p>Carregando execução auditável…</p></section>
  {:else if path === '/'}
    <Home overview={data.overview} houses={data.houses} trend={data.trend} events={data.events} feed={data.feed} coverage={data.coverage} operations={data.operations} {period} {onPeriodChange} />
  {:else if path === '/institutos'}
    <Institutes houses={data.houses} overview={data.overview} />
  {:else if houseId}
    {#if detailError}
      <section class="load-state error-state" role="alert"><h1>Ficha indisponível</h1><p>{detailError}</p><a href="/institutos" data-route>Voltar aos institutos</a></section>
    {:else if detail}
      <House {detail} overview={data.overview} trend={data.trend} />
    {:else}
      <section class="load-state" aria-live="polite"><p>Carregando ficha auditável…</p></section>
    {/if}
  {:else if path === '/pesquisas'}
    <Polls payload={data.polls} overview={data.overview} {initialHouse} />
  {:else if path === '/metodologia'}
    <Methods methods={data.methods} backtest={data.backtest} manifest={data.manifest} houses={data.houses} polls={data.polls} />
  {:else if path === '/laboratorio'}
    <Lab {data} />
  {:else}
    <section class="load-state"><p class="eyebrow">404</p><h1>Página não encontrada</h1><a href="/" data-route>Voltar à Visão geral</a></section>
  {/if}
</main>

{#if data}<Footer manifest={data.manifest} disclaimer={data.overview.disclaimer} />{/if}
