export const candidateColors = ['#2a78d6', '#eb6834', '#1baf7a', '#eda100', '#e87ba4'] as const;
export const othersColor = '#898781';

export function colorForSlot(slot: number): string {
  if (slot >= 1 && slot <= candidateColors.length) {
    return candidateColors[slot - 1];
  }
  return othersColor;
}

export function candidateColor(candidateId: string, candidates: Array<{ id: string; slot: number }>): string {
  return colorForSlot(candidates.find((candidate) => candidate.id === candidateId)?.slot ?? 0);
}

