<script lang="ts">
  import AuditValue from './AuditValue.svelte';
  import { candidateColor } from '../lib/palette';
  import type { Candidate, CandidateMetric } from '../lib/types';

  export let item: CandidateMetric;
  export let candidate: Candidate;
  export let candidates: Candidate[];
  export let muted = false;

  const maxScale = 60;
  $: q10 = item.value.q10 ?? item.value.q50;
  $: q25 = item.value.q25 ?? item.value.q50;
  $: q75 = item.value.q75 ?? item.value.q50;
  $: q90 = item.value.q90 ?? item.value.q50;
  $: color = candidateColor(item.candidate_id, candidates);
  $: band80 = `left:${Math.max(0, q10 / maxScale * 100)}%;width:${Math.max(0, (q90 - q10) / maxScale * 100)}%`;
  $: band50 = `left:${Math.max(0, q25 / maxScale * 100)}%;width:${Math.max(0, (q75 - q25) / maxScale * 100)}%`;
  $: point = `left:${Math.min(100, Math.max(0, item.value.q50 / maxScale * 100))}%;background:${color}`;
</script>

<div class:muted class="estimate-strip" data-slot={candidate.slot} style={`--candidate:${color}`}>
  <div class="estimate-label">
    <span class="candidate-dot" aria-hidden="true"></span>
    <span>{candidate.short_name}</span>
  </div>
  <div
    class="strip-track"
    role="img"
    aria-label={`${item.value.kind} de ${candidate.name}: ${item.value.q50.toFixed(1)}%, faixa de 80% de ${q10.toFixed(1)}% a ${q90.toFixed(1)}%`}
  >
    <span class="band band-80" style={band80}></span>
    <span class="band band-50" style={band50}></span>
    <span class="strip-point" style={point}></span>
  </div>
  <AuditValue metric={item.value} compact />
</div>
